import build_nano_v3_dataset as nano_builder

PUA_RE = re.compile(r"[\uee00-\uf8ff]")
KANJI_RE = re.compile(r"[\u4e00-\u9fff]")
HIRA_RE = re.compile(r"[\u3041-\u3096]")


def hira_to_kata(text: str) -> str:
    return "".join(chr(ord(c) + 96) if 0x3041 <= ord(c) <= 0x3096 else c for c in text)


def make_row(left_context: str, reading_hira_or_kata: str, completion: str, category: str, family: str) -> dict:
    kata = hira_to_kata(reading_hira_or_kata)
    if PUA_RE.search(left_context) or PUA_RE.search(kata) or PUA_RE.search(completion):
        raise ValueError(f"PUA character found in row: {left_context} | {kata} | {completion}")
    if KANJI_RE.search(kata) or HIRA_RE.search(kata):
        raise ValueError(f"Non-katakana reading found: {kata} (for completion: {completion})")
    prompt = f"\uee02{left_context}\uee00{kata}\uee01" if left_context else f"\uee00{kata}\uee01"
    return {
        "prompt": prompt,
        "completion": completion,
        "left_context": left_context,
        "reading": kata,
        "expected": completion,
        "category": category,
        "family": family,
    }


def collect_raw_rows(reserved_keys: set[str]):
    eval_ctx_norm = set()
    for p in EVALUATION_FILES:
        for c in load_jsonl(p):
            ctx = c.get("left_context")
            if ctx and ctx != "なし":
                eval_ctx_norm.add(normalize(ctx))

    rows = []
    seen_pairs = set()

    def add(left: str, reading: str, completion: str, cat: str, fam: str):
        raw_row = make_row(left, reading, completion, cat, fam)
        if source_keys(raw_row) & reserved_keys:
            return False
        if left and normalize(left) in eval_ctx_norm:
            return False
        m_left, m_reading, m_comp = nano_builder.mask_row_digits_with_nam(
            left, raw_row["reading"], completion
        )
        row = make_row(m_left, m_reading, m_comp, cat, fam)
        r_keys = source_keys(row)
        if r_keys & reserved_keys:
            return False
        if m_left and normalize(m_left) in eval_ctx_norm:
            return False
        pair_key = (row["prompt"], row["completion"])
        if pair_key in seen_pairs:
            return False
        seen_pairs.add(pair_key)
        rows.append(row)
        return True

    # 0. Inherit clean rows from Nano v3
    for r in nano_builder.collect_curated_families(reserved_keys):
        if r["prompt"].startswith("\uee02\uee00"):
            r["prompt"] = "\uee00" + r["prompt"][2:]
        r_keys = source_keys(r)
        if not (r_keys & reserved_keys):
            if not (r.get("left_context") and normalize(r["left_context"]) in eval_ctx_norm):
                pair_key = (r["prompt"], r["completion"])
                if pair_key not in seen_pairs:
                    seen_pairs.add(pair_key)
                    rows.append(r)

